import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int M = fs.nextInt();

        List<Integer>[] adj1 = new ArrayList[N];
        for (int i = 0; i < N; i++) adj1[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            adj1[a].add(b);
            adj1[b].add(a);
        }

        List<Integer>[] adj2 = new ArrayList[M];
        for (int i = 0; i < M; i++) adj2[i] = new ArrayList<>();

        for (int i = 0; i < M - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            adj2[a].add(b);
            adj2[b].add(a);
        }

        int center1 = findCenter(N, adj1);
        int center2 = findCenter(M, adj2);

        System.out.println(center1 + " " + center2);
    }

    static int findCenter(int n, List<Integer>[] adj) {
        int[] dist = new int[n];
        int[] parent = new int[n];
        int[] queue = new int[n];

        int a = bfs(0, adj, dist, parent, queue);
        int b = bfs(a, adj, dist, parent, queue);

        int diameterEdges = dist[b];
        int cur = b;

        for (int i = 0; i < diameterEdges / 2; i++) {
            cur = parent[cur];
        }

        return cur + 1;
    }

    static int bfs(int start, List<Integer>[] adj, int[] dist, int[] parent, int[] queue) {
        Arrays.fill(dist, -1);

        int head = 0, tail = 0;
        dist[start] = 0;
        parent[start] = -1;
        queue[tail++] = start;

        int far = start;

        while (head < tail) {
            int u = queue[head++];

            if (dist[u] > dist[far]) {
                far = u;
            }

            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    queue[tail++] = v;
                }
            }
        }

        return far;
    }
}
